INSERT INTO operation_log (
    uuid, project_id, engineering_id, task_id, log_date, content,
    creator_id, create_time, update_by, update_time, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{projectId}, #{engineeringId}, #{taskId}, #{logDate}, #{content},
